# Verify demo again precisely with function f:
def f(grid):
    from collections import Counter
    # separator value: most common overall? use full-constant rows/cols
    sep=None
    for v in range(10):
        if sum(row.count(v) for row in grid)>=len(grid)*len(grid)//3 and any(all(x==v for x in row) for row in grid) or any(all(row[c]==v for c in range(len(row))) for row in grid): sep=v
    # bands
    band=[]; start=0
    for r in range(len(grid)):
        if all(x==sep for x in grid[r]):
            if band: band.append((start,r-1)); start=r+1
    if band: band.append((start,len(grid)-1))
    gcol=[c for c in range(len(grid[0])) if all(row[c]==sep for row in grid)]
    grp=[]; start=0
    for c in range(len(grid[0])):
        if c in gcol:
            if grp: grp.append((start,c-1)); start=c+1
    if grp: grp.append((start,len(grid[0])-1))
    cnt_all=Counter(x for row in grid for x in row)
    bg=max((k for k,v in cnt_all.items() if k!=sep), key=lambda k: cnt_all[k])
    out=[]
    for (r0,r1) in band:
        line=[]
        for (c0,c1) in grp:
            blk=[grid[r][c] for r in range(r0,r1+1) for c in range(c0,c1+1)]
            n=sum(x!=bg for x in blk)
            line.append(1 if n%2==0 else bg)
        out.append(line)
    return out
